package dns.resolver

import java.net.{DatagramPacket, DatagramSocket, InetAddress}
import java.util.concurrent.{ConcurrentHashMap, CountDownLatch, TimeUnit}
import java.util.concurrent.atomic.AtomicBoolean
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

trait ResolverStrategy {
  def resolve(query: String): Option[String]
  def shutdown(): Unit
}

class CachingResolver extends ResolverStrategy {
  private val cache = new ConcurrentHashMap[String, String]()
  override def resolve(query: String): Option[String] = Option(cache.get(query))
  override def shutdown(): Unit = cache.clear()
}

object StrategyRegistry {
  private val allowedStrategies: Set[String] = Set(
    "dns.resolver.CachingResolver",
    "dns.resolver.ForwardingResolver",
    "dns.resolver.RecursiveResolver"
  )

  def isAllowed(className: String): Boolean = {
    val normalized = className.trim.replaceAll("\\s+", "")
    allowedStrategies.exists(allowed => normalized.startsWith(allowed))
  }
}

class DnsServer(port: Int, strategyClassName: String) {
  private val running = new AtomicBoolean(false)
  private val shutdownLatch = new CountDownLatch(1)
  private var socket: DatagramSocket = _
  private var strategy: ResolverStrategy = _
  private val shutdownHooks = mutable.ListBuffer[() => Unit]()

  def registerShutdownHook(hook: () => Unit): Unit = {
    shutdownHooks.synchronized {
      shutdownHooks += hook
    }
  }

  private def loadStrategy(className: String): ResolverStrategy = {
    if (!StrategyRegistry.isAllowed(className)) {
      throw new SecurityException(s"Strategy not in allowlist: $className")
    }
    val clazz = Class.forName(className)
    clazz.getDeclaredConstructor().newInstance().asInstanceOf[ResolverStrategy]
  }

  def start(): Unit = {
    strategy = loadStrategy(strategyClassName)
    socket = new DatagramSocket(port)
    running.set(true)

    registerShutdownHook(() => {
      strategy.shutdown()
    })

    val serverThread = new Thread(() => {
      val buffer = new Array[Byte](512)
      while (running.get()) {
        try {
          val packet = new DatagramPacket(buffer, buffer.length)
          socket.receive(packet)
          handlePacket(packet)
        } catch {
          case _: java.net.SocketException if !running.get() => // expected during shutdown
          case e: Exception => System.err.println(s"Error: ${e.getMessage}")
        }
      }
      shutdownLatch.countDown()
    })
    serverThread.setDaemon(true)
    serverThread.start()
  }

  private def handlePacket(packet: DatagramPacket): Unit = {
    val data = new String(packet.getData, 0, packet.getLength, "UTF-8")
    val parts = data.split("\\|")
    if (parts.length >= 2) {
      val command = parts(0)
      val payload = parts(1)

      command match {
        case "RESOLVE" =>
          val result = strategy.resolve(payload).getOrElse("NXDOMAIN")
          sendResponse(packet, result)
        case "RELOAD_STRATEGY" =>
          reloadStrategy(payload)
        case _ =>
          sendResponse(packet, "ERROR: Unknown command")
      }
    }
  }

  private def reloadStrategy(newStrategySpec: String): Unit = {
    val specParts = newStrategySpec.split("#")
    val baseClassName = specParts(0)
    val fullClassName = if (specParts.length > 1) {
      // Support inner class notation: OuterClass#InnerClass -> OuterClass$InnerClass
      baseClassName + "$" + specParts(1)
    } else {
      baseClassName
    }
    Try(loadStrategy(fullClassName)) match {
      case Success(newStrategy) =>
        val oldStrategy = strategy
        strategy = newStrategy
        oldStrategy.shutdown()
      case Failure(e) =>
        System.err.println(s"Failed to reload strategy: ${e.getMessage}")
    }
  }

  private def sendResponse(request: DatagramPacket, response: String): Unit = {
    val responseBytes = response.getBytes("UTF-8")
    val responsePacket = new DatagramPacket(
      responseBytes, responseBytes.length,
      request.getAddress, request.getPort
    )
    socket.send(responsePacket)
  }

  def gracefulShutdown(timeoutMs: Long = 5000): Unit = {
    running.set(false)
    shutdownHooks.synchronized {
      shutdownHooks.foreach(hook => Try(hook()))
    }
    Try(socket.close())
    shutdownLatch.await(timeoutMs, TimeUnit.MILLISECONDS)
  }
}

object DnsServerApp {
  def main(args: Array[String]): Unit = {
    val port = args.headOption.flatMap(s => Try(s.toInt).toOption).getOrElse(5353)
    val strategy = if (args.length > 1) args(1) else "dns.resolver.CachingResolver"
    val server = new DnsServer(port, strategy)
    server.start()
    Runtime.getRuntime.addShutdownHook(new Thread(() => server.gracefulShutdown()))
  }
}
